  1→export interface AdditionalMount {
  2→  hostPath: string; // Absolute path on host (supports ~ for home)
  3→  containerPath?: string; // Optional — defaults to basename of hostPath. Mounted at /workspace/extra/{value}
  4→  readonly?: boolean; // Default: true for safety
  5→}
  6→
  7→/**
  8→ * Mount Allowlist - Security configuration for additional mounts
  9→ * This file should be stored at ~/.config/nanoclaw/mount-allowlist.json
 10→ * and is NOT mounted into any container, making it tamper-proof from agents.
 11→ */
 12→export interface MountAllowlist {
 13→  // Directories that can be mounted into containers
 14→  allowedRoots: AllowedRoot[];
 15→  // Glob patterns for paths that should never be mounted (e.g., ".ssh", ".gnupg")
 16→  blockedPatterns: string[];
 17→  // If true, non-main groups can only mount read-only regardless of config
 18→  nonMainReadOnly: boolean;
 19→}
 20→
 21→export interface AllowedRoot {
 22→  // Absolute path or ~ for home (e.g., "~/projects", "/var/repos")
 23→  path: string;
 24→  // Whether read-write mounts are allowed under this root
 25→  allowReadWrite: boolean;
 26→  // Optional description for documentation
 27→  description?: string;
 28→}
 29→
 30→export interface ContainerConfig {
 31→  additionalMounts?: AdditionalMount[];
 32→  timeout?: number; // Default: 300000 (5 minutes)
 33→}
 34→
 35→export interface RegisteredGroup {
 36→  name: string;
 37→  folder: string;
 38→  trigger: string;
 39→  added_at: string;
 40→  containerConfig?: ContainerConfig;
 41→  requiresTrigger?: boolean; // Default: true for groups, false for solo chats
 42→  isMain?: boolean; // True for the main control group (no trigger, elevated privileges)
 43→}
 44→
 45→export interface NewMessage {
 46→  id: string;
 47→  chat_jid: string;
 48→  sender: string;
 49→  sender_name: string;
 50→  content: string;
 51→  timestamp: string;
 52→  is_from_me?: boolean;
 53→  is_bot_message?: boolean;
 54→}
 55→
 56→export interface ScheduledTask {
 57→  id: string;
 58→  group_folder: string;
 59→  chat_jid: string;
 60→  prompt: string;
 61→  schedule_type: 'cron' | 'interval' | 'once';
 62→  schedule_value: string;
 63→  context_mode: 'group' | 'isolated';
 64→  next_run: string | null;
 65→  last_run: string | null;
 66→  last_result: string | null;
 67→  status: 'active' | 'paused' | 'completed';
 68→  created_at: string;
 69→}
 70→
 71→export interface TaskRunLog {
 72→  task_id: string;
 73→  run_at: string;
 74→  duration_ms: number;
 75→  status: 'success' | 'error';
 76→  result: string | null;
 77→  error: string | null;
 78→}
 79→
 80→// --- Channel abstraction ---
 81→
 82→export interface Channel {
 83→  name: string;
 84→  connect(): Promise<void>;
 85→  sendMessage(jid: string, text: string): Promise<void>;
 86→  isConnected(): boolean;
 87→  ownsJid(jid: string): boolean;
 88→  disconnect(): Promise<void>;
 89→  // Optional: typing indicator. Channels that support it implement it.
 90→  setTyping?(jid: string, isTyping: boolean): Promise<void>;
 91→  // Optional: sync group/chat names from the platform.
 92→  syncGroups?(force: boolean): Promise<void>;
 93→}
 94→
 95→// Callback type that channels use to deliver inbound messages
 96→export type OnInboundMessage = (chatJid: string, message: NewMessage) => void;
 97→
 98→// Callback for chat metadata discovery.
 99→// name is optional — channels that deliver names inline (Telegram) pass it here;
100→// channels that sync names separately (via syncGroups) omit it.
101→export type OnChatMetadata = (
102→  chatJid: string,
103→  timestamp: string,
104→  name?: string,
105→  channel?: string,
106→  isGroup?: boolean,
107→) => void;
